import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import * as m0 from "../../src/lib/description-meter.ts";

const source = (path) => readFileSync(new URL('../../' + path, import.meta.url), 'utf8');

test("1. src/lib/description-meter.ts exports DESCRIPTION_MIN_WORDS, describeDescription", async () => {
  assert.notEqual(m0["DESCRIPTION_MIN_WORDS"], undefined, "DESCRIPTION_MIN_WORDS");
  assert.notEqual(m0["describeDescription"], undefined, "describeDescription");
});

test("2. describeDescription(\"\") returns \"0 words \\u00b7 1 min read \\u00b7 Short: aim for at least 30 words\"", async () => {
  assert.equal(typeof m0.describeDescription, 'function');
  assert.deepEqual(await m0.describeDescription(...[""]), "0 words \u00b7 1 min read \u00b7 Short: aim for at least 30 words");
});

test("3. describeDescription(\"One\") returns \"1 word \\u00b7 1 min read \\u00b7 Short: aim for at least 30 words\"", async () => {
  assert.equal(typeof m0.describeDescription, 'function');
  assert.deepEqual(await m0.describeDescription(...["One"]), "1 word \u00b7 1 min read \u00b7 Short: aim for at least 30 words");
});

test("4. describeDescription(\"word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word\") returns \"30 words \\u00b7 1 min read\"", async () => {
  assert.equal(typeof m0.describeDescription, 'function');
  assert.deepEqual(await m0.describeDescription(...["word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word"]), "30 words \u00b7 1 min read");
});

test("5. describeDescription(\"  word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word", async () => {
  assert.equal(typeof m0.describeDescription, 'function');
  assert.deepEqual(await m0.describeDescription(...["  word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word\n"]), "201 words \u00b7 2 min read");
});

test("6. src/lib/description-meter.ts contains \"from \\\"./reading-time.ts\\\"\"", async () => {
  assert.ok(source("src/lib/description-meter.ts").includes("from \"./reading-time.ts\""));
});

test("7. src/app/dashboard/draft-review.tsx contains \"import { describeDescription } from \\\"@/lib/description-meter\\\"\"", async () => {
  assert.ok(source("src/app/dashboard/draft-review.tsx").includes("import { describeDescription } from \"@/lib/description-meter\""));
});

test("8. src/app/dashboard/draft-review.tsx contains \"<p className=\\\"description-meter\\\" aria-live=\\\"polite\\\">{describeDescription(description)}</p>\"", async () => {
  assert.ok(source("src/app/dashboard/draft-review.tsx").includes("<p className=\"description-meter\" aria-live=\"polite\">{describeDescription(description)}</p>"));
});

test("9. src/app/dashboard/draft-review.tsx contains \"Save review\"", async () => {
  assert.ok(source("src/app/dashboard/draft-review.tsx").includes("Save review"));
});

test("10. src/app/dashboard/draft-review.tsx contains \"Approve exact version\"", async () => {
